  1 │ // ponytail: Intl only; swap for Temporal.ZonedDateTime once Node and Safari ship it
  2 │ 
  3 │ const formatters = new Map<string, Intl.DateTimeFormat>();
  4 │ 
  5 │ // Slot building calls these hundreds of times per request, so formatters are built once per locale, zone and options.
  6 │ function formatter(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  7 │   const key = `${locale}|${timeZone}|${JSON.stringify(options)}`;
  8 │   let f = formatters.get(key);
  9 │   if (!f) {
 10 │     f = new Intl.DateTimeFormat(locale, { ...options, timeZone }); // throws on a junk zone, before the cache is touched
 11 │     if (formatters.size > 500) formatters.clear(); // ponytail: clear-all past 500 entries; an LRU if real zones ever churn
 12 │     formatters.set(key, f);
 13 │   }
 14 │   return f;
 15 │ }
 16 │ 
 17 │ // ICU accepts "IST" and maps it to India, so a zone without a "/" is only valid as "UTC" (spec §7 rule 8).
 18 │ export function isValidTimeZone(tz: string): boolean {
 19 │   if (tz !== 'UTC' && !tz.includes('/')) return false;
 20 │   try {
 21 │     formatter('en-US', tz, {});
 22 │     return true;
 23 │   } catch {
 24 │     return false;
 25 │   }
 26 │ }
 27 │ 
 28 │ /** UTC offset of `tz` at the instant `at`, in minutes (-240, 330). */
 29 │ export function offsetMinutes(at: Date, tz: string): number {
 30 │   const name = formatter('en-US', tz, { timeZoneName: 'longOffset' })
 31 │     .formatToParts(at)
 32 │     .find((p) => p.type === 'timeZoneName')?.value;
 33 │   if (name === 'GMT') return 0;
 34 │   const m = name?.match(/^GMT([+\-−])(\d\d):(\d\d)$/);
 35 │   if (!m) throw new Error(`cannot read the UTC offset of ${tz}: ${name}`);
 36 │   return (m[1] === '+' ? 1 : -1) * (Number(m[2]) * 60 + Number(m[3]));
 37 │ }
 38 │ 
 39 │ /** The calendar date at `at` in `tz`, as 'YYYY-MM-DD'. */
 40 │ export function localDate(at: Date, tz: string): string {
 41 │   const parts = formatter('en-US', tz, { year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(at);
 42 │   const part = (type: string) => parts.find((p) => p.type === type)?.value;
 43 │   return `${part('year')}-${part('month')}-${part('day')}`;
 44 │ }
 45 │ 
 46 │ function parseDate(date: string): [number, number, number] {
 47 │   const [y, m, d] = date.split('-').map(Number);
 48 │   return [y!, m!, d!];
 49 │ }
 50 │ 
 51 │ /** Day of the week of a calendar date, 0 = Sunday. */
 52 │ export function weekdayOf(date: string): number {
 53 │   const [y, m, d] = parseDate(date);
 54 │   return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
 55 │ }
 56 │ 
 57 │ export function addDays(date: string, days: number): string {
 58 │   const [y, m, d] = parseDate(date);
 59 │   return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
 60 │ }
 61 │ 
 62 │ /**
 63 │  * The instant at which `tz` reads `date` `time` ('HH:MM' or 'HH:MM:SS').
 64 │  * Matches Temporal's 'compatible' rule: a repeated hour resolves to its first pass,
 65 │  * and a time skipped by a clock change moves forward by the gap.
 66 │  */
 67 │ export function zonedTimeToInstant(date: string, time: string, tz: string): Date {
 68 │   const [y, m, d] = parseDate(date);
 69 │   const [hh, mm, ss = 0] = time.split(':').map(Number);
 70 │   const wall = Date.UTC(y, m - 1, d, hh!, mm!, ss); // the wall-clock reading as if it were UTC
 71 │   const early = offsetMinutes(new Date(wall - 86_400_000), tz);
 72 │   const late = offsetMinutes(new Date(wall + 86_400_000), tz);
 73 │   const valid = [early, late]
 74 │     .map((o) => wall - o * 60_000)
 75 │     .filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
 76 │   // repeated hour: two valid instants, take the earlier; gap: none valid, move forward by the gap
 77 │   return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
 78 │ }
 79 │ 
 80 │ /** 'GMT', 'GMT+1', 'GMT+5:30', 'GMT-4' for an offset in minutes. */
 81 │ export function formatOffset(minutes: number): string {
 82 │   if (minutes === 0) return 'GMT';
 83 │   const abs = Math.abs(minutes);
 84 │   const rest = abs % 60 ? `:${String(abs % 60).padStart(2, '0')}` : '';
 85 │   return `GMT${minutes < 0 ? '-' : '+'}${Math.floor(abs / 60)}${rest}`;
 86 │ }
 87 │ 
 88 │ /** The name people there use for the zone at `at` ('BST', 'IST', 'EDT'), or 'GMT+9' when no English locale names it. */
 89 │ export function zoneAbbreviation(at: Date, tz: string): string {
 90 │   // ponytail: six English locales cover the zones we serve; add a per-zone map if one picks a wrong name
 91 │   for (const locale of ['en-US', 'en-GB', 'en-IE', 'en-IN', 'en-CA', 'en-AU']) {
 92 │     const name = formatter(locale, tz, { timeZoneName: 'short' })
 93 │       .formatToParts(at)
 94 │       .find((p) => p.type === 'timeZoneName')?.value;
 95 │     if (name && !/^(GMT|UTC)[+-]/.test(name)) return name;
 96 │   }
 97 │   return formatOffset(offsetMinutes(at, tz));
 98 │ }
 99 │ 
100 │ const CITY_ALIASES: Record<string, string> = {
101 │   'Asia/Calcutta': 'Kolkata',
102 │   'Europe/Kiev': 'Kyiv',
103 │   'Asia/Saigon': 'Ho Chi Minh City',
104 │ };
105 │ 
106 │ export function cityName(tz: string): string {
107 │   return CITY_ALIASES[tz] ?? tz.slice(tz.lastIndexOf('/') + 1).replaceAll('_', ' ');
108 │ }
109 │ 
110 │ /** ICU's own spelling of a zone, so 'Asia/Kolkata' and 'Asia/Calcutta' compare equal. */
111 │ export function canonicalTimeZone(tz: string): string {
112 │   return formatter('en', tz, {}).resolvedOptions().timeZone;
113 │ }
114 │ 
115 │ /** '4:00 PM', with a plain space where ICU puts a narrow no-break one. */
116 │ export function formatTime(at: Date, tz: string): string {
117 │   return formatter('en-US', tz, { hour: 'numeric', minute: '2-digit' }).format(at).replace(/\u202f/g, ' ');
118 │ }
119 │ 
120 │ /** 'Tue 27 Oct' */
121 │ export function formatDate(at: Date, tz: string): string {
122 │   return formatter('en-GB', tz, { weekday: 'short', day: 'numeric', month: 'short' }).format(at);
123 │ }
124 │ 
125 │ /** 'Tue 27 Oct 2026' (en-GB would put a comma after the weekday if asked for the year too) */
126 │ export function formatDateWithYear(at: Date, tz: string): string {
127 │   return `${formatDate(at, tz)} ${formatter('en-GB', tz, { year: 'numeric' }).format(at)}`;
128 │ }
129 │ 
130 │ /** A 'YYYY-MM-DD' calendar day as 'Sun 25 Oct'. */
131 │ export function formatDayKey(key: string): string {
132 │   return formatDate(new Date(`${key}T12:00:00Z`), 'UTC');
133 │ }
134 │ 
135 │ /** 'BST (London)' */
136 │ export function formatZone(at: Date, tz: string): string {
137 │   return `${zoneAbbreviation(at, tz)} (${cityName(tz)})`;
138 │ }
139 │ 
140 │ /** 'Fri 23 Oct, 4:00 PM BST (London)', the display style used in the UI and the emails. */
141 │ export function formatWhen(at: Date, tz: string): string {
142 │   return `${formatDate(at, tz)}, ${formatTime(at, tz)} ${formatZone(at, tz)}`;
143 │ }
144 │ 
145 │ /** '4:00–5:00 PM GMT (London)'; names both zones when a clock change falls inside the span. */
146 │ export function formatSpan(start: Date, end: Date, tz: string): string {
147 │   const from = formatTime(start, tz);
148 │   const to = formatTime(end, tz);
149 │   const city = cityName(tz);
150 │   if (offsetMinutes(start, tz) !== offsetMinutes(end, tz)) {
151 │     return `${from} ${zoneAbbreviation(start, tz)}–${to} ${zoneAbbreviation(end, tz)} (${city})`;
152 │   }
153 │   const samePeriod = from.slice(-2) === to.slice(-2); // 'AM' or 'PM'
154 │   return `${samePeriod ? from.slice(0, -3) : from}–${to} ${zoneAbbreviation(start, tz)} (${city})`;
155 │ }
156 │ 
157 │ /** 'London (GMT+1)', the label in the zone picker. */
158 │ export function formatZoneOption(at: Date, tz: string): string {
159 │   return `${cityName(tz)} (${formatOffset(offsetMinutes(at, tz))})`;
160 │ }
161 │ 
162 │ /** The time in `tz` for a reader in `viewerTz`: '9:30 PM IST', with the date when the two sides are on different days. */
163 │ export function formatOtherTime(at: Date, tz: string, viewerTz: string): string {
164 │   const time = `${formatTime(at, tz)} ${zoneAbbreviation(at, tz)}`;
165 │   return localDate(at, tz) === localDate(at, viewerTz) ? time : `${formatDate(at, tz)}, ${time}`;
166 │ }
