 1 │ import { readdir, readFile } from 'node:fs/promises';
 2 │ import pg from 'pg';
 3 │ 
 4 │ // pg turns a `date` into local midnight, which shifts a day in zones east of UTC. Keep it a plain 'YYYY-MM-DD'.
 5 │ pg.types.setTypeParser(pg.types.builtins.DATE, (v) => v);
 6 │ 
 7 │ const MIGRATION_LOCK = 727001;
 8 │ 
 9 │ export function createPool(connectionString: string, max?: number): pg.Pool {
10 │   const pool = new pg.Pool({ connectionString, max });
11 │   // pg-pool stops listening for errors on a checked-out client; without this a dropped connection mid-transaction crashes the process.
12 │   // A query in flight already rejects with the error, and any later query on the dead client rejects too, so nothing is lost by ignoring the event.
13 │   pool.on('connect', (client) => client.on('error', () => {}));
14 │   pool.on('error', (err: Error & { code?: string }) => {
15 │     // 57P01: the server ended an idle connection, as a test teardown's `drop database ... with (force)` does.
16 │     if (err.code !== '57P01') console.error('postgres pool error', err);
17 │   });
18 │   return pool;
19 │ }
20 │ 
21 │ export async function migrate(pool: pg.Pool): Promise<string[]> {
22 │   const dir = new URL('../../migrations/', import.meta.url);
23 │   const client = await pool.connect();
24 │   try {
25 │     await client.query('select pg_advisory_lock($1)', [MIGRATION_LOCK]);
26 │     await client.query(
27 │       'create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now())',
28 │     );
29 │     const done = new Set((await client.query('select name from schema_migrations')).rows.map((r) => r.name));
30 │     const applied: string[] = [];
31 │     for (const name of (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()) {
32 │       if (done.has(name)) continue;
33 │       const sql = await readFile(new URL(name, dir), 'utf8');
34 │       try {
35 │         await client.query('begin');
36 │         await client.query(sql);
37 │         await client.query('insert into schema_migrations (name) values ($1)', [name]);
38 │         await client.query('commit');
39 │       } catch (err) {
40 │         await client.query('rollback');
41 │         throw err;
42 │       }
43 │       applied.push(name);
44 │     }
45 │     return applied;
46 │   } finally {
47 │     try {
48 │       await client.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK]);
49 │     } finally {
50 │       client.release();
51 │     }
52 │   }
53 │ }
 1 │ import { addDays, localDate, weekdayOf, zonedTimeToInstant } from '../shared/time.ts';
 2 │ 
 3 │ export const CLASS_MINUTES = 60, LEAD_MINUTES = 120, HORIZON_DAYS = 14, DAILY_CAP = 2;
 4 │ 
 5 │ const MINUTE_MS = 60_000;
 6 │ const HOUR_MS = 60 * MINUTE_MS;
 7 │ const CLASS_MS = CLASS_MINUTES * MINUTE_MS;
 8 │ 
 9 │ export type WorkingHours = { weekday: number; start: string; end: string }; // 'HH:MM', in the mentor's own time zone
10 │ export type Mentor = { id: number; name: string; email: string; bio: string; subjects: string[]; timeZone: string; hours: WorkingHours[] };
11 │ export type ActiveBooking = { mentorId: number; startsAt: Date; mentorLocalDate: string };
12 │ export type Slot = { startsAt: Date; available: boolean };
13 │ 
14 │ /** On the UTC hour, and inside [now + 120 minutes, now + 14 days], both ends inclusive. */
15 │ export function isBookableTime(startsAt: Date, now: Date): boolean {
16 │   const t = startsAt.getTime();
17 │   return t % HOUR_MS === 0 && t >= now.getTime() + LEAD_MINUTES * MINUTE_MS && t <= now.getTime() + HORIZON_DAYS * 24 * HOUR_MS;
18 │ }
19 │ 
20 │ /** The mentor's working windows on one of their own calendar days, as [open, close] in epoch ms. */
21 │ function windows(mentor: Mentor, date: string): [number, number][] {
22 │   const weekday = weekdayOf(date);
23 │   return mentor.hours
24 │     .filter((h) => h.weekday === weekday)
25 │     .map((h) => [zonedTimeToInstant(date, h.start, mentor.timeZone).getTime(), zonedTimeToInstant(date, h.end, mentor.timeZone).getTime()]);
26 │ }
27 │ 
28 │ /** True when the whole class fits one working-hours window on the mentor's own day. */
29 │ export function worksAt(mentor: Mentor, startsAt: Date): boolean {
30 │   const t = startsAt.getTime();
31 │   return windows(mentor, localDate(startsAt, mentor.timeZone)).some(([open, close]) => t >= open && t + CLASS_MS <= close);
32 │ }
33 │ 
34 │ /** Class starts on the UTC hour inside [from, to], sorted and unique. */
35 │ export function classStarts(mentor: Mentor, from: Date, to: Date): Date[] {
36 │   const starts = new Set<number>();
37 │   // a day either side is purely defensive; walking the mentor's own local dates already covers a UTC-date straddle
38 │   const last = addDays(localDate(to, mentor.timeZone), 1);
39 │   for (let date = addDays(localDate(from, mentor.timeZone), -1); date <= last; date = addDays(date, 1)) {
40 │     for (const [open, close] of windows(mentor, date)) {
41 │       for (let t = Math.ceil(open / HOUR_MS) * HOUR_MS; t + CLASS_MS <= close; t += HOUR_MS) {
42 │         if (t >= from.getTime() && t <= to.getTime()) starts.add(t);
43 │       }
44 │     }
45 │   }
46 │   return [...starts].sort((a, b) => a - b).map((t) => new Date(t));
47 │ }
48 │ 
49 │ /** Every bookable hour, open or full, sorted by start. An hour is open when any mentor working it is free and under the daily cap. */
50 │ export function buildSlots(mentors: Mentor[], bookings: ActiveBooking[], now: Date): Slot[] {
51 │   const taken = new Set(bookings.map((b) => `${b.mentorId}|${b.startsAt.getTime()}`));
52 │   const perDay = new Map<string, number>();
53 │   for (const b of bookings) {
54 │     const key = `${b.mentorId}|${b.mentorLocalDate}`;
55 │     perDay.set(key, (perDay.get(key) ?? 0) + 1);
56 │   }
57 │ 
58 │   const from = new Date(now.getTime() + LEAD_MINUTES * MINUTE_MS);
59 │   const to = new Date(now.getTime() + HORIZON_DAYS * 24 * HOUR_MS);
60 │   const open = new Map<number, boolean>();
61 │   for (const mentor of mentors) {
62 │     for (const start of classStarts(mentor, from, to)) {
63 │       const t = start.getTime();
64 │       const free = !taken.has(`${mentor.id}|${t}`) && (perDay.get(`${mentor.id}|${localDate(start, mentor.timeZone)}`) ?? 0) < DAILY_CAP;
65 │       open.set(t, (open.get(t) ?? false) || free);
66 │     }
67 │   }
68 │   return [...open].sort((a, b) => a[0] - b[0]).map(([t, available]) => ({ startsAt: new Date(t), available }));
69 │ }
  1 │ import { randomUUID } from 'node:crypto';
  2 │ import type pg from 'pg';
  3 │ import { localDate } from '../shared/time.ts';
  4 │ import { DAILY_CAP, isBookableTime, worksAt, type ActiveBooking, type Mentor } from './slots.ts';
  5 │ 
  6 │ export type BookingInput = { startsAt: Date; parentName: string; parentEmail: string; childName: string; parentTimeZone: string };
  7 │ export type Booking = BookingInput & { id: string; mentorId: number; mentorLocalDate: string; classLink: string; cancelledAt: Date | null };
  8 │ export type BookResult = { ok: true; booking: Booking } | { ok: false; code: 'SLOT_UNAVAILABLE' };
  9 │ 
 10 │ const UNAVAILABLE = { ok: false, code: 'SLOT_UNAVAILABLE' } as const;
 11 │ 
 12 │ export function newClassLink(): string {
 13 │   return `https://classroom.example/trial/${randomUUID()}`;
 14 │ }
 15 │ 
 16 │ function toBooking(r: any): Booking {
 17 │   return {
 18 │     id: r.id,
 19 │     mentorId: r.mentor_id,
 20 │     startsAt: r.starts_at,
 21 │     mentorLocalDate: r.mentor_local_date,
 22 │     parentName: r.parent_name,
 23 │     parentEmail: r.parent_email,
 24 │     childName: r.child_name,
 25 │     parentTimeZone: r.parent_time_zone,
 26 │     classLink: r.class_link,
 27 │     cancelledAt: r.cancelled_at,
 28 │   };
 29 │ }
 30 │ 
 31 │ /** Every mentor with their weekly hours ('HH:MM', in the mentor's own time zone), ordered by id. */
 32 │ export async function loadMentors(pool: pg.Pool): Promise<Mentor[]> {
 33 │   const [mentors, hours] = await Promise.all([
 34 │     pool.query('select id, name, email, bio, subjects, time_zone from mentors order by id'),
 35 │     pool.query('select mentor_id, weekday, start_time, end_time from mentor_hours order by mentor_id, weekday, start_time'),
 36 │   ]);
 37 │   return mentors.rows.map((m) => ({
 38 │     id: m.id,
 39 │     name: m.name,
 40 │     email: m.email,
 41 │     bio: m.bio,
 42 │     subjects: m.subjects,
 43 │     timeZone: m.time_zone,
 44 │     hours: hours.rows
 45 │       .filter((h) => h.mentor_id === m.id)
 46 │       .map((h) => ({ weekday: h.weekday, start: h.start_time.slice(0, 5), end: h.end_time.slice(0, 5) })),
 47 │   }));
 48 │ }
 49 │ 
 50 │ /** Active bookings with from <= starts_at < to. */
 51 │ export async function loadActiveBookings(pool: pg.Pool, from: Date, to: Date): Promise<ActiveBooking[]> {
 52 │   const { rows } = await pool.query(
 53 │     'select mentor_id, starts_at, mentor_local_date from bookings where cancelled_at is null and starts_at >= $1 and starts_at < $2',
 54 │     [from, to],
 55 │   );
 56 │   return rows.map((r) => ({ mentorId: r.mentor_id, startsAt: r.starts_at, mentorLocalDate: r.mentor_local_date }));
 57 │ }
 58 │ 
 59 │ /** Books the hour with the least-booked free mentor (lowest id on a tie), or says SLOT_UNAVAILABLE. Never sends email. */
 60 │ export async function bookSlot(
 61 │   pool: pg.Pool,
 62 │   input: BookingInput,
 63 │   now: Date,
 64 │   hooks?: { beforeInsert?: () => Promise<void> },
 65 │ ): Promise<BookResult> {
 66 │   if (!isBookableTime(input.startsAt, now)) return UNAVAILABLE;
 67 │ 
 68 │   const candidates = (await loadMentors(pool))
 69 │     .filter((m) => worksAt(m, input.startsAt))
 70 │     .map((mentor) => ({ mentor, date: localDate(input.startsAt, mentor.timeZone) }));
 71 │   if (candidates.length === 0) return UNAVAILABLE;
 72 │ 
 73 │   // How loaded each candidate is that day. A stale count only affects the order; the locked check below decides.
 74 │   const { rows } = await pool.query(
 75 │     `select mentor_id, mentor_local_date, count(*)::int as n from bookings
 76 │      where cancelled_at is null and mentor_id = any($1) and mentor_local_date = any($2)
 77 │      group by mentor_id, mentor_local_date`,
 78 │     [candidates.map((c) => c.mentor.id), candidates.map((c) => c.date)],
 79 │   );
 80 │   const load = new Map<string, number>(rows.map((r) => [`${r.mentor_id}|${r.mentor_local_date}`, r.n]));
 81 │   const loadOf = (c: (typeof candidates)[number]) => load.get(`${c.mentor.id}|${c.date}`) ?? 0;
 82 │   candidates.sort((a, b) => loadOf(a) - loadOf(b) || a.mentor.id - b.mentor.id);
 83 │ 
 84 │   for (const { mentor, date } of candidates) {
 85 │     const client = await pool.connect();
 86 │     try {
 87 │       await client.query('begin isolation level read committed');
