 13 │ export type Day = { key: string; slots: SlotDto[]; openCount: number };
 14 │ 
 15 │ /** Exactly 14 local days from today in `tz`, each holding the slots that start on it. */
 16 │ export function groupIntoDays(slots: SlotDto[], tz: string, now: Date): Day[] {
 17 │   const today = localDate(now, tz);
 18 │   const days: Day[] = Array.from({ length: DAYS_SHOWN }, (_, i) => ({ key: addDays(today, i), slots: [], openCount: 0 }));
 19 │   const byKey = new Map(days.map((d) => [d.key, d]));
 20 │   for (const s of slots) {
 21 │     const day = byKey.get(localDate(new Date(s.startsAt), tz));
 22 │     if (!day) continue;
 23 │     day.slots.push(s);
 24 │     if (s.available) day.openCount++;
 25 │   }
 26 │   return days;
 27 │ }
 28 │ 
 29 │ /** The day to show: the selected time's own day (it must stay on screen after a zone change), else the chosen day, else the first open one. */
 30 │ export function shownDayKey(days: Day[], selected: string | null, chosenDay: string | null, tz: string): string {
 31 │   const has = (key: string) => days.some((d) => d.key === key);
 32 │   const selectedDay = selected && localDate(new Date(selected), tz);
 33 │   if (selectedDay && has(selectedDay)) return selectedDay;
 34 │   if (chosenDay && has(chosenDay)) return chosenDay;
 35 │   return (days.find((d) => d.openCount > 0) ?? days[0])!.key;
 36 │ }
 37 │ 
 38 │ /** The open times closest to `target` (never `target` itself), in time order. */
 39 │ export function nearestOpenTimes(slots: SlotDto[], target: string, count = 3): string[] {
 40 │   const at = new Date(target).getTime();
 41 │   return slots
 42 │     .filter((s) => s.available && new Date(s.startsAt).getTime() !== at)
 43 │     .map((s) => ({ startsAt: s.startsAt, t: new Date(s.startsAt).getTime() }))
 44 │     .sort((a, b) => Math.abs(a.t - at) - Math.abs(b.t - at) || a.t - b.t)
 45 │     .slice(0, count)
 46 │     .sort((a, b) => a.t - b.t)
 47 │     .map((s) => s.startsAt);
 48 │ }
 49 │ 
 50 │ /** The closest days with an open time before and after `key`. */
 51 │ export function nearestOpenDays(days: Day[], key: string): { before: Day | null; after: Day | null } {
 52 │   const open = days.filter((d) => d.openCount > 0);
 53 │   return { before: open.findLast((d) => d.key < key) ?? null, after: open.find((d) => d.key > key) ?? null };
 54 │ }
 55 │ 
 56 │ /** The first day in the window whose midday offset differs from today's, with the zone names either side. */
 57 │ export function clockChange(days: Day[], tz: string, now: Date): { dayKey: string; from: string; to: string } | null {
 58 │   const offset = offsetMinutes(now, tz);
 59 │   for (const { key } of days) {
 60 │     const noon = zonedTimeToInstant(key, '12:00', tz);
 61 │     if (offsetMinutes(noon, tz) !== offset) return { dayKey: key, from: zoneAbbreviation(now, tz), to: zoneAbbreviation(noon, tz) };
 62 │   }
 63 │   return null;
 64 │ }
