 66 │ /** True on the day a clock change falls inside, where one day's times carry two zone names. */
 67 │ export function dayMixesOffsets(day: Day, tz: string): boolean {
 68 │   return new Set(day.slots.map((s) => offsetMinutes(new Date(s.startsAt), tz))).size > 1;
