107 │ /** A mentor's booked times grouped into the mentor's own days, in time order. `times` are the input strings, untouched. */
108 │ export function mentorDays(bookings: { startsAt: string }[], tz: string): MentorDay[] {
109 │   const days = new Map<string, MentorDay>();
110 │   for (const { startsAt } of [...bookings].sort((a, b) => new Date(a.startsAt).getTime() - new Date(b.startsAt).getTime())) {
111 │     const key = localDate(new Date(startsAt), tz);
112 │     const day = days.get(key) ?? { key, times: [], atCap: false };
113 │     day.times.push(startsAt);
114 │     day.atCap = day.times.length >= 2;
115 │     days.set(key, day);
116 │   }
117 │   return [...days.values()];
118 │ }
