16 │ async function request<T>(path: string, init?: RequestInit): Promise<T> {
17 │   let res: Response;
18 │   try {
19 │     res = await fetch(path, init);
20 │   } catch {
21 │     // offline or the server is down: a 5xx so queries retry it
22 │     throw new ApiError(503, 'INTERNAL', "We can't reach the server. Check your connection and try again.");
