27 │     return body as T;
28 │   }
29 │   const error = (body as ApiErrorBody | null)?.error;
30 │   throw new ApiError(res.status, error?.code ?? 'INTERNAL', error?.message ?? 'Something went wrong. Please try again.', error?.fields);
